const fleetPhotos=[{src:'images/crawler.jpg',alt:'Orange crawler cranes at a construction site',label:'THE CRAWLER SERIES'},{src:'images/mobile.jpg',alt:'Liebherr mobile crane deployed beside a terminal construction site',label:'THE MOBILE SERIES'},{src:'images/tower.webp',alt:'Yellow tower crane above a concrete building under construction',label:'THE TOWER SERIES'}];
window.updateFleetPhoto=function(i){const p=fleetPhotos[i];const image=document.querySelector('#fleet-photo');image.src=p.src;image.alt=p.alt;document.querySelector('.photo-label').textContent=p.label;document.querySelector('.photo-index').textContent='0'+(i+1)+' / 03';};
document.querySelectorAll('[data-fleet]').forEach((button,i)=>{const image=document.createElement('img');image.src=fleetPhotos[i].src;image.alt='';image.loading='lazy';button.prepend(image)});
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{const photo=button.dataset.view==='photo';document.querySelector('.hero').classList.toggle('photo-mode',photo);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button)});document.querySelector('.crane-stage').setAttribute('aria-hidden',photo);document.querySelector('.blueprint-toggle').tabIndex=photo?-1:0;});
document.querySelector('.crane-stage').setAttribute('aria-hidden','true');document.querySelector('.blueprint-toggle').tabIndex=-1;
